// Three equal sign-in options, all visible: Google, Apple, email link. Providers hide only when their flag is off.
// After the link is sent, this screen also accepts the code printed in that email.
// Sessions persist on device (supabase-js persistSession), so members sign in once.
import React, { useEffect, useRef, useState, type ComponentRef } from 'react';
import { ActivityIndicator, Dimensions, Image, Keyboard, KeyboardAvoidingView, Platform, ScrollView, Text, View } from 'react-native';
import { Link, router, useLocalSearchParams, useRootNavigationState } from 'expo-router';
import { initialWindowMetrics } from 'react-native-safe-area-context';
import { Button, Field, styles } from '../components/ui';
import { colors, fonts, fs } from '../lib/theme';
import { FEATURES, PRODUCT_NAME } from '../lib/config';
import { SIGNED_IN_HOME, clearReturnPath, noteExplicitLanding, readReturnPath, rememberReturnPath, sendMagicLink, signInWithApple, signInWithGoogle, verifyEmailCode } from '../lib/auth';
import { emailCodeDigits, emailCodeReady } from '../lib/email-code';
import { KEYBOARD_SETTLE_FRAMES, KEYBOARD_TAIL_CATCH_UP, coveredByKeyboard, keyboardTopFromEvent, nextKeyboardTail, scrollOffsetToReveal, visualKeyboardOverlap } from '../lib/keyboard-inset';
import { reportWebAuth } from '../lib/ga-web';
import { useSession } from '../lib/session';

const CUSHION = 16;

type Box = { x: number; y: number; width: number; height: number };
type Measurable = { measureInWindow?: (cb: (x: number, y: number, width: number, height: number) => void) => void };
type Scroller = { scrollTo?: (opts: { y: number; animated?: boolean }) => void };

function measureBox(node: unknown, cb: (box: Box) => void) {
  const view = node as Measurable | null;
  if (view && typeof view.measureInWindow === 'function') {
    view.measureInWindow((x, y, width, height) => cb({ x, y, width, height }));
  }
}

function scrollToY(node: unknown, y: number, animated: boolean) {
  (node as Scroller | null)?.scrollTo?.({ y, animated });
}

export default function SignIn() {
  const { userId } = useSession();
  const nextRaw = useLocalSearchParams<{ next?: string | string[] }>().next;
  const nextParam = Array.isArray(nextRaw) ? nextRaw[0] : nextRaw;
  const [email, setEmail] = useState('');
  const [code, setCode] = useState('');
  const [status, setStatus] = useState<'idle' | 'sending' | 'sent' | 'verifying'>('idle');
  const [error, setError] = useState<string | null>(null);
  const nav = useRootNavigationState();
  const sent = useRef(false);
  const verifying = useRef(false);
  const scrollRef = useRef<ComponentRef<typeof ScrollView>>(null);
  const frameRef = useRef<ComponentRef<typeof View>>(null);
  const viewportRef = useRef<ComponentRef<typeof View>>(null);
  const emailBlockRef = useRef<ComponentRef<typeof View>>(null);
  const scrollY = useRef(0);
  const tailRef = useRef(0);
  // Bottom edge of the visible area, in the same coordinates as measureInWindow.
  const keyboardLimitRef = useRef<number | null>(null);
  const keyboardDurationRef = useRef(0);
  // Distance from the physical top of the screen to this view. The shell pads
  // the status bar outside the screen, and the nested safe-area context reports
  // top as 0, so KeyboardAvoidingView's parent-relative y would stop short.
  const [offset, setOffset] = useState(() => (
    Platform.OS === 'web' ? 0 : Math.max(0, Math.round(initialWindowMetrics?.insets.top ?? 0))
  ));
  // Extra scroll padding when the avoiding view has not cleared the keyboard
  // (web, where KeyboardAvoidingView is a no-op, or a shortfall on native).
  const [tail, setTail] = useState(0);
  const [keyboardOpen, setKeyboardOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      // The write must finish before the read. On Android AsyncStorage is async,
      // so a same-turn read still returned the previous path (often /chat).
      if (nextParam) await rememberReturnPath(nextParam);
      if (cancelled || !userId || sent.current || !nav?.key) return;
      const next = await readReturnPath();
      if (cancelled || sent.current) return;
      sent.current = true;
      clearReturnPath();
      if (next) noteExplicitLanding(next);
      router.replace(next ?? SIGNED_IN_HOME);
    })();
    return () => { cancelled = true; };
  }, [userId, nextParam, nav?.key]);

  const revealRef = useRef<(attempt: number) => void>(() => {});
  revealRef.current = (attempt: number) => {
    const scroll = scrollRef.current;
    const emailBlock = emailBlockRef.current;
    const viewport = viewportRef.current;
    if (!scroll || !emailBlock || !viewport) return;
    measureBox(viewport, (view) => {
      if (view.height < 1 && attempt < KEYBOARD_SETTLE_FRAMES) {
        requestAnimationFrame(() => revealRef.current(attempt + 1));
        return;
      }
      const limit = keyboardLimitRef.current;
      const stillCovered = limit == null ? 0 : coveredByKeyboard(view.y, view.height, limit);
      // Give KeyboardAvoidingView a few frames to pad before adding our own.
      if (stillCovered > KEYBOARD_TAIL_CATCH_UP && attempt < KEYBOARD_SETTLE_FRAMES) {
        requestAnimationFrame(() => revealRef.current(attempt + 1));
        return;
      }
      const nextTail = nextKeyboardTail(view.y, view.height, limit, tailRef.current);
      if (nextTail > tailRef.current) {
        tailRef.current = nextTail;
        setTail(nextTail);
      }
      measureBox(emailBlock, (block) => {
        const edge = keyboardLimitRef.current;
        const visibleBottom = edge == null ? view.y + view.height : Math.min(view.y + view.height, edge);
        const next = scrollOffsetToReveal(scrollY.current, block.y, block.y + block.height, view.y, visibleBottom, CUSHION);
        if (next > scrollY.current + 1) {
          scrollY.current = next;
          scrollToY(scroll, next, true);
        }
      });
    });
  };

  useEffect(() => {
    if (Platform.OS !== 'web' || typeof window === 'undefined') return;
    const vv = window.visualViewport;
    if (!vv) return;
    const sync = () => {
      const overlap = visualKeyboardOverlap(window.innerHeight, vv.height, vv.offsetTop);
      keyboardLimitRef.current = overlap > 0 ? vv.height : null;
      keyboardDurationRef.current = 0;
      const open = overlap > 0;
      tailRef.current = overlap;
      setTail((prev) => (prev === overlap ? prev : overlap));
      setKeyboardOpen((prev) => (prev === open ? prev : open));
    };
    vv.addEventListener('resize', sync);
    vv.addEventListener('scroll', sync);
    sync();
    return () => {
      vv.removeEventListener('resize', sync);
      vv.removeEventListener('scroll', sync);
    };
  }, []);

  useEffect(() => {
    if (Platform.OS === 'web') return;
    const showEvent = Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
    const hideEvent = Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';
    const show = Keyboard.addListener(showEvent, (e) => {
      const top = keyboardTopFromEvent(e.endCoordinates.screenY, e.endCoordinates.height, Dimensions.get('window').height);
      keyboardLimitRef.current = top;
      keyboardDurationRef.current = Platform.OS === 'ios' ? Math.max(0, e.duration ?? 250) : 0;
      setKeyboardOpen(top != null);
    });
    const hide = Keyboard.addListener(hideEvent, () => {
      keyboardLimitRef.current = null;
      keyboardDurationRef.current = 0;
      tailRef.current = 0;
      setTail(0);
      setKeyboardOpen(false);
    });
    return () => {
      show.remove();
      hide.remove();
    };
  }, []);

  useEffect(() => {
    if (!keyboardOpen) {
      scrollY.current = 0;
      scrollToY(scrollRef.current, 0, false);
      return;
    }
    // Wait out the iOS keyboard animation on the first lift. A later tail
    // correction should measure the layout that just committed.
    const delay = tail > 0 ? 0 : keyboardDurationRef.current;
    const id = setTimeout(() => revealRef.current(0), delay);
    return () => clearTimeout(id);
  }, [keyboardOpen, tail]);

  const onFrameLayout = () => {
    if (Platform.OS === 'web') return;
    measureBox(frameRef.current, (frame) => {
      const next = Math.max(0, Math.round(frame.y));
      setOffset((prev) => (Math.abs(prev - next) <= 1 ? prev : next));
    });
  };

  // If our fallback padding landed and the avoiding view then caught up, drop
  // the extra padding so the card is not followed by a blank gap.
  const onViewportLayout = () => {
    const limit = keyboardLimitRef.current;
    if (limit == null || tailRef.current <= 0) return;
    measureBox(viewportRef.current, (view) => {
      const nextTail = nextKeyboardTail(view.y, view.height, limit, tailRef.current);
      if (nextTail < tailRef.current) {
        tailRef.current = nextTail;
        setTail(nextTail);
      }
    });
  };

  if (userId) return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;

  const valid = /^\S+@\S+\.\S+$/.test(email.trim());
  const codeReady = emailCodeReady(code);
  const awaitingCode = status === 'sent' || status === 'verifying';
  const submit = async () => {
    if (!valid || status === 'sending') return;
    setError(null); setStatus('sending');
    try {
      await sendMagicLink(email);
      Keyboard.dismiss();
      setCode('');
      setStatus('sent');
    } catch (e: any) { setError(e.message ?? 'Something went wrong'); setStatus('idle'); }
  };
  const submitCode = async () => {
    if (!codeReady || verifying.current) return;
    verifying.current = true;
    setError(null);
    setStatus('verifying');
    try {
      const user = await verifyEmailCode(email, code);
      reportWebAuth(user);
      Keyboard.dismiss();
    } catch (e: any) {
      verifying.current = false;
      setError(e?.message || 'Something went wrong');
      setStatus('sent');
    }
  };
  const backToEmail = () => {
    verifying.current = false;
    setCode('');
    setError(null);
    setStatus('idle');
  };
  const run = (fn: () => Promise<void>) => () => {
    setError(null);
    fn().catch((e) => {
      // An empty message must not clear the line: the tap would look like a no-op.
      Keyboard.dismiss();
      setError(e?.message || 'Something went wrong');
    });
  };
  const providers = FEATURES.googleSignIn || FEATURES.appleSignIn;

  return (
    <View ref={frameRef} style={{ flex: 1 }} onLayout={onFrameLayout}>
      {/* Android edge-to-edge keeps the window full height, so padding (not an
          undefined behavior) has to lift the screen. Scroll the card; don't squish it. */}
      <KeyboardAvoidingView
        behavior={Platform.OS === 'web' ? undefined : 'padding'}
        keyboardVerticalOffset={offset}
        style={{ flex: 1 }}
      >
        <View ref={viewportRef} style={{ flex: 1 }} collapsable={false} onLayout={onViewportLayout}>
          <ScrollView
            ref={scrollRef}
            style={{ flex: 1 }}
            keyboardShouldPersistTaps="handled"
            onScroll={(e) => { scrollY.current = e.nativeEvent.contentOffset.y; }}
            scrollEventThrottle={16}
            contentContainerStyle={{ flexGrow: 1, paddingHorizontal: 28, paddingTop: 28, paddingBottom: 28 + tail }}
          >
            <View style={{ flexGrow: 1, flexShrink: 0, justifyContent: 'center', alignItems: 'center' }}>
              <View style={[styles.highlight, { width: '100%', maxWidth: 400, padding: 28 }]}>
                <View style={{ alignItems: 'center', marginBottom: 28 }}>
                  <Image source={require('../assets/brand/logo.png')} style={{ width: 64, height: 64 }} resizeMode="contain" accessibilityLabel={PRODUCT_NAME} />
                  <Text style={[styles.h1, { marginTop: 14 }]}>{PRODUCT_NAME}</Text>
                </View>

                {awaitingCode ? (
                  <View style={{ alignItems: 'center', gap: 6, alignSelf: 'stretch' }}>
                    <Text style={styles.h2}>Check your email</Text>
                    <Text style={styles.muted}>{email.trim()}</Text>
                    <View ref={emailBlockRef} collapsable={false} style={{ alignSelf: 'stretch', marginTop: 12 }}>
                      <Field value={code} onChangeText={(value) => { setCode(emailCodeDigits(value)); setError(null); }} placeholder="Code"
                        autoCapitalize="none" autoCorrect={false} autoFocus keyboardType="number-pad" inputMode="numeric"
                        textContentType="oneTimeCode" autoComplete="one-time-code" returnKeyType="done"
                        onSubmitEditing={submitCode} onFocus={() => revealRef.current(0)} accessibilityLabel="Email code" />
                      <Button title="Sign in" onPress={submitCode} disabled={!codeReady} loading={status === 'verifying'} style={{ marginTop: -4 }} />
                      {error ? <Text style={{ color: colors.danger, fontFamily: fonts.sans, textAlign: 'center', marginTop: 4 }}>{error}</Text> : null}
                    </View>
                    <Button title="Back" variant="ghost" small style={{ marginTop: 12 }} onPress={backToEmail} />
                  </View>
                ) : (
                  <View style={{ gap: 10 }}>
                    {FEATURES.googleSignIn ? <Button title="Continue with Google" variant="secondary" onPress={run(signInWithGoogle)} /> : null}
                    {FEATURES.appleSignIn ? <Button title="Continue with Apple" variant="secondary" onPress={run(signInWithApple)} /> : null}
                    {providers ? <Text style={[styles.muted, { textAlign: 'center', marginVertical: 4, fontSize: fs(12) }]}>or</Text> : null}
                    <View ref={emailBlockRef} collapsable={false}>
                      <Field value={email} onChangeText={setEmail} placeholder="Email address" autoCapitalize="none" autoFocus={Platform.OS === 'web' || !providers}
                        keyboardType="email-address" autoComplete="email" textContentType="emailAddress" returnKeyType="send"
                        onSubmitEditing={submit} onFocus={() => revealRef.current(0)} accessibilityLabel="Email address" />
                      <Button title="Email me a link" onPress={submit} disabled={!valid} loading={status === 'sending'} style={{ marginTop: -4 }} />
                      {error ? <Text style={{ color: colors.danger, fontFamily: fonts.sans, textAlign: 'center', marginTop: 4 }}>{error}</Text> : null}
                    </View>
                  </View>
                )}

                <Text style={[styles.muted, { textAlign: 'center', marginTop: 24, fontSize: fs(12) }]}>
                  By continuing you agree to the <Link href="/guidelines" style={{ textDecorationLine: 'underline' }}>Guidelines</Link>.
                </Text>
              </View>
            </View>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>
    </View>
  );
}
